-- Sample tables the e2e suite reads: Senegal's regions and departments, and a
-- year of weekly malaria cases per region. The Data Studio, database, saved
-- query and search specs assert on their values (14 regions, 45 departments,
-- 52 weeks), so keep the data and those expectations in step.
--
-- Nothing here is real health data. The boundaries are public administrative
-- data, with their outlines simplified to about a kilometre to keep this file
-- small; the malaria figures are synthetic, computed below from a formula.
--
-- Load it into the test workspace's database with psql, connected as the
-- workspace's own (read-write) role so the tables belong to it:
--
--   psql "$WORKSPACE_DATABASE_URL" -v ON_ERROR_STOP=1 -f seed-tables.sql
--
-- It needs the postgis extension, which workspace databases have, and can be
-- run again: it replaces the three tables.

BEGIN;

DROP TABLE IF EXISTS public.level_2_region, public.level_3_department, public.malaria_cases_weekly;

CREATE TABLE public.level_2_region (
    fid serial PRIMARY KEY,
    ref character varying,
    name character varying,
    parent_ref character varying,
    code character varying,
    geom public.geometry(MultiPolygon,4326)
);

CREATE TABLE public.level_3_department (
    fid serial PRIMARY KEY,
    ref character varying,
    name character varying,
    parent_ref character varying,
    code character varying,
    geom public.geometry(MultiPolygon,4326)
);

CREATE TABLE public.malaria_cases_weekly (
    region_code character varying,
    epi_week integer,
    confirmed_cases integer,
    PRIMARY KEY (region_code, epi_week)
);



SELECT pg_catalog.setval('public.level_2_region_fid_seq', (SELECT max(fid) FROM public.level_2_region));
SELECT pg_catalog.setval('public.level_3_department_fid_seq', (SELECT max(fid) FROM public.level_3_department));

CREATE INDEX level_2_region_geom_geom_idx ON public.level_2_region USING gist (geom);
CREATE INDEX level_3_department_geom_geom_idx ON public.level_3_department USING gist (geom);

-- Synthetic: a baseline that differs per region, and a peak around week 40,
-- after the rains.
SELECT
    region.code,
    week,
    round((20 + 15 * region.fid) * (1 + 6 * exp(-power(week - 40, 2) / 40.0)))
FROM public.level_2_region AS region
CROSS JOIN generate_series(1, 52) AS week;

COMMIT;
